import java.util.*;

class Solution {
    public int[][] merge(int[][] intervals) {
        PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        for (int[] interval : intervals) {
            minHeap.offer(new int[] {interval[0], interval[1]});
        }

        List<int[]> result = new ArrayList<>();
        while (!minHeap.isEmpty()) {
            int[] interval = minHeap.poll();
            if (result.isEmpty() || result.get(result.size() - 1)[1] < interval[0]) {
                result.add(interval);
            } else {
                int[] last = result.get(result.size() - 1);
                last[1] = Math.max(last[1], interval[1]);
            }
        }
        return result.toArray(new int[result.size()][]);
    }
}

class Solution {
    public int[][] merge(int[][] intervals) {
        int n = intervals.length;
        int[] starts = new int[n];
        int[] ends = new int[n];
        for (int i = 0; i < n; i++) {
            starts[i] = intervals[i][0];
            ends[i] = intervals[i][1];
        }
        java.util.Arrays.sort(starts);
        java.util.Arrays.sort(ends);

        java.util.List<int[]> result = new java.util.ArrayList<>();
        int startIndex = 0;
        for (int i = 0; i < n; i++) {
            if (i == n - 1 || starts[i + 1] > ends[i]) {
                result.add(new int[] {starts[startIndex], ends[i]});
                startIndex = i + 1;
            }
        }
        return result.toArray(new int[result.size()][]);
    }
}

import java.util.*;

class Solution {
    public int[][] merge(int[][] intervals) {
        TreeMap<Integer, int[]> events = new TreeMap<>();
        for (int[] interval : intervals) {
            addEvent(events, interval[0], 1, 0);
            addEvent(events, interval[1], 0, 1);
        }

        List<int[]> result = new ArrayList<>();
        int active = 0;
        int currentStart = -1;
        for (Map.Entry<Integer, int[]> entry : events.entrySet()) {
            int coordinate = entry.getKey();
            int starts = entry.getValue()[0];
            int ends = entry.getValue()[1];
            if (active == 0 && starts > 0) {
                currentStart = coordinate;
            }
            active += starts;
            active -= ends;
            if (active == 0) {
                result.add(new int[] {currentStart, coordinate});
            }
        }
        return result.toArray(new int[result.size()][]);
    }

    private void addEvent(TreeMap<Integer, int[]> events, int coordinate, int starts, int ends) {
        int[] counts = events.computeIfAbsent(coordinate, key -> new int[2]);
        counts[0] += starts;
        counts[1] += ends;
    }
}

import java.util.*;

class Solution {
    public int[][] merge(int[][] intervals) {
        int n = intervals.length;
        boolean[] visited = new boolean[n];
        List<int[]> result = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (visited[i]) {
                continue;
            }
            int start = intervals[i][0];
            int end = intervals[i][1];
            Deque<Integer> stack = new ArrayDeque<>();
            visited[i] = true;
            stack.push(i);

            while (!stack.isEmpty()) {
                int current = stack.pop();
                start = Math.min(start, intervals[current][0]);
                end = Math.max(end, intervals[current][1]);
                for (int next = 0; next < n; next++) {
                    if (!visited[next] && overlaps(intervals[current], intervals[next])) {
                        visited[next] = true;
                        stack.push(next);
                    }
                }
            }
            result.add(new int[] {start, end});
        }

        result.sort((a, b) -> Integer.compare(a[0], b[0]));
        return result.toArray(new int[result.size()][]);
    }

    private boolean overlaps(int[] a, int[] b) {
        return a[0] <= b[1] && b[0] <= a[1];
    }
}
